const amqp = require('amqplib');

async function startConsumer(queueName) {
  const conn = await amqp.connect('amqp://localhost');
  const ch = await conn.createChannel();

  await ch.assertExchange('stock.trades', 'fanout', { durable: true });

  const { queue } = await ch.assertQueue('', { exclusive: true });
  await ch.bindQueue(queue, 'stock.trades', '');

  console.log(`[${queueName}] Waiting for messages...`);
  ch.consume(queue, (msg) => {
    if (msg.content) {
      console.log(`[${queueName}] Received: ${msg.content.toString()}`);
    }
  }, { noAck: true });
}

startConsumer('audit-service');
